package com.acaivis.model;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDateTime;
@Entity @Table(name="products")
public class Product { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private String name; @Column(nullable=false) private String size; @Column(nullable=false,length=500) private String description; @Column(nullable=false,precision=10,scale=2) private BigDecimal price; @Column(name="image_url",length=500) private String imageUrl; @Column(length=60) private String badge; @Column(name="stock_quantity",nullable=false) private Integer stockQuantity=0; @Column(nullable=false) private boolean available=true; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="category_id",nullable=false) private Category category; @Column(name="created_at",nullable=false,updatable=false) private LocalDateTime createdAt; @Column(name="updated_at",nullable=false) private LocalDateTime updatedAt; @PrePersist void pre(){createdAt=LocalDateTime.now();updatedAt=createdAt;} @PreUpdate void upd(){updatedAt=LocalDateTime.now();}
 public Long getId(){return id;} public String getName(){return name;} public void setName(String v){name=v;} public String getSize(){return size;} public void setSize(String v){size=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public BigDecimal getPrice(){return price;} public void setPrice(BigDecimal v){price=v;} public String getImageUrl(){return imageUrl;} public void setImageUrl(String v){imageUrl=v;} public String getBadge(){return badge;} public void setBadge(String v){badge=v;} public Integer getStockQuantity(){return stockQuantity;} public void setStockQuantity(Integer v){stockQuantity=v;} public boolean isAvailable(){return available;} public void setAvailable(boolean v){available=v;} public Category getCategory(){return category;} public void setCategory(Category v){category=v;} public LocalDateTime getCreatedAt(){return createdAt;} public LocalDateTime getUpdatedAt(){return updatedAt;}
}
